1	/**
2	 * Interaction rules used by the schedule builder to accept or refuse a drop.
3	 *
4	 * ─────────────────────────────────────────────────────────────────────────────
5	 * SEED DATA. This list is a starting point, not a clinical reference. It covers
6	 * four well-documented interactions and nothing else, which means the builder
7	 * will happily accept plenty of combinations it should question. Expanding it
8	 * is a research task with a citable source per rule, not a coding one — add
9	 * `source` to each entry when that happens.
10	 * ─────────────────────────────────────────────────────────────────────────────
11	 *
12	 * Matching is by substring against the lowercased item name, so "Zinc
13	 * picolinate" matches the `zinc` rule. That is deliberately loose: a missed
14	 * warning is worse than an occasional over-eager one.
15	 */
16	
17	export interface GapRule {
18	  kind: 'gap';
19	  a: string;
20	  b: string;
21	  minGapMinutes: number;
22	  message: string;
23	  /** soft rules explain themselves but do not block the drop */
24	  severity: 'block' | 'warn';
25	}
26	
27	export interface AnchorRule {
28	  kind: 'anchor';
29	  item: string;
30	  requires: 'meal' | 'evening';
31	  /** how close to the anchor it has to land */
32	  withinMinutes: number;
33	  message: string;
34	  severity: 'block' | 'warn';
35	}
36	
37	export type ConflictRule = GapRule | AnchorRule;
38	
39	export const CONFLICT_RULES: ConflictRule[] = [
40	  {
41	    kind: 'gap',
42	    a: 'zinc',
43	    b: 'iron',
44	    minGapMinutes: 120,
45	    message: 'Zinc and iron need about 2 hours between them.',
46	    severity: 'block',
47	  },
48	  {
49	    kind: 'gap',
50	    a: 'calcium',
51	    b: 'zinc',
52	    minGapMinutes: 120,
53	    message: 'Calcium and zinc compete for absorption — about 2 hours apart works better.',
54	    severity: 'warn',
55	  },
56	  {
57	    kind: 'anchor',
58	    item: 'omega-3',
59	    requires: 'meal',
60	    withinMinutes: 60,
61	    message: 'Omega-3 needs a meal. Try moving it to within an hour of one.',
62	    severity: 'block',
63	  },
64	  {
65	    kind: 'anchor',
66	    item: 'magnesium',
67	    requires: 'evening',
68	    withinMinutes: 120,
69	    message: 'Magnesium works better in your wind-down window.',
70	    severity: 'warn',
71	  },
