1	import type { GlossaryEntry } from './api';
2	
3	/**
4	 * The recommendation rule table.
5	 *
6	 * Pure and synchronous — entries in, an ordered list out. No fetching, no
7	 * randomness, no model call, nothing that cannot be read off the page. Every
8	 * rule below states the reason it fired and that reason is what the card
9	 * shows; a rule that cannot say why in one sentence does not belong here.
10	 *
11	 * Two things this deliberately does not do. It never removes a nutrient
12	 * because of a reaction — a reaction changes which product, not whether — and
13	 * it never invents a sentence. An entry that no rule touched carries the goal
14	 * match it already had, and an entry with neither carries nothing at all.
15	 */
16	
17	/* ── what the user told us ───────────────────────────────────────────── */
18	
19	export interface Answers {
20	  /** the goal tags the user's picks expand to; the caller owns that mapping */
21	  goalTags: string[];
22	  /** how to name those goals in a sentence — 'your goals', or 'sleep' */
23	  goalLabel: string;
24	  /** free text from the "what are you already taking" screen */
25	  currentStack: string[];
26	  /** `diet` ids from the onboarding store: no-meat, no-fish, … */
27	  diet: string[];
28	  /** `reactions` ids: iron-gi, mag-gi, … */
29	  reactions: string[];
30	  /** `forms` ids: capsule, powder, … */
31	  forms: string[];
32	}
33	
34	export interface Suggestion {
35	  entry: GlossaryEntry;
36	  /** higher first; see the weights below for what each rule is worth */
37	  score: number;
38	  /** the goal tags this entry matched, for the fallback reason */
39	  goalHits: string[];
40	  /** the one line the card shows. Empty when nothing fired — show nothing. */
41	  reason: string;
42	  /** multiplier on the reference intake where a rule adjusts it; 1 otherwise */
43	  amountFactor: number;
44	  /** a reaction can force this even where the product's own timing differs */
45	  timing: 'with_food' | null;
46	}
47	
48	/** A product a rule routed away from, and the plain reason why. */
49	export interface SwappedOut {
50	  name: string;
51	  why: string;
52	}
53	
54	export interface RecommendResult {
55	  /** everything that survived, best first. The caller decides how many to show. */
56	  ranked: Suggestion[];
57	  swappedOut: SwappedOut[];
58	  /** names from the catalogue the user said they already take */
59	  alreadyTaking: string[];
60	}
61	
62	/* ── weights ─────────────────────────────────────────────────────────── */
63	
64	/**
65	 * One goal tag is worth 10, so a rule worth 30 outranks any realistic goal
66	 * overlap and a rule worth 6 only breaks ties. `required` is worth more than
67	 * anything else can add up to, because "no reliable plant source" is not a
68	 * ranking argument.
69	 */
70	const W = {
71	  goalHit: 10,
72	  required: 1000,
73	  dietPriority: 30,
74	  preferredForm: 25,
75	  swallowable: 12,
76	  formPreference: 6,
77	} as const;
78	
79	const EVIDENCE = { strong: 2, mixed: 1, thin: 0 } as const;
80	
81	/** Reason priority — the highest that fired is the one the card shows. */
82	const P = {
83	  required: 60,
84	  swap: 50,
85	  diet: 40,
86	  timing: 30,
87	  swallowable: 20,
88	  formPreference: 10,
89	  goal: 0,
90	} as const;
91	
92	/* ── recognising a nutrient ──────────────────────────────────────────── */
93	
94	/**
95	 * Name, slug and search keywords together — everything the catalogue holds
96	 * that says what a product *is*. Deliberately not the brand: matching Thorne
97	 * would match a quarter of the library. Deliberately not the mechanism or
98	 * research summary either, which mention neighbouring nutrients constantly.
99	 *
100	 * Slugs are matched as well as names so this survives item 0.5 renaming them
101	 * from ingredient-shaped to `<brand>-<product>` — both shapes contain the
102	 * ingredient.
103	 */
104	const textOf = (e: GlossaryEntry) =>
105	  `${e.name} ${e.slug} ${(e.search_keywords ?? []).join(' ')}`.toLowerCase();
106	
107	const hits = (text: string, terms: readonly RegExp[]) => terms.some((t) => t.test(text));
108	
109	/**
110	 * Word-bounded, so "iron" does not match inside another word and "niacin"
111	 * does not match "niacinamide" — the two forms of B3 are the whole point of
112	 * one of the rules below and must stay distinguishable.
113	 */
114	const NUTRIENT = {
115	  b12: [/\bb-?12\b/, /cobalamin/],
116	  iron: [/\biron\b/, /ferrous/, /ferric/],
117	  zinc: [/\bzinc\b/],
118	  magnesium: [/\bmagnesium\b/],
119	  omega3: [/\bomega[\s-]?3\b/, /\bdha\b/, /\bepa\b/, /fish oil/, /\bkrill\b/, /cod liver/],
120	  calcium: [/\bcalcium\b/],
121	  vitaminD: [/\bvitamin\s?d\b/, /\bd-?3\b/, /cholecalciferol/],
122	  // choline bitartrate and anything else that names choline. Citicoline and
123	  // alpha-GPC raise choline too but spell neither, and they are catalogued as
124	  // cognitive products — left out rather than quietly folded in.
125	  choline: [/choline/],
126	  niacin: [/niacin/, /nicotinamide/, /nicotinic/],
127	} as const;
128	
129	/**
130	 * Whether this entry is an iron product, by the same matcher the iron rules
131	 * above use. Exported because `src/lib/intake.ts` has to recognise the same
132	 * set — iron is the one reference intake that turns on menstrual status, and
133	 * two definitions of "is this iron" would drift the first time a product is
134	 * called something unexpected.
135	 */
136	export const isIron = (entry: GlossaryEntry) => hits(textOf(entry), NUTRIENT.iron);
137	
138	/* ── product form ────────────────────────────────────────────────────── */
139	
140	export type FormClass = 'capsule' | 'softgel' | 'tablet' | 'powder' | 'liquid' | 'gummy' | 'other';
141	
142	/**
143	 * DSLD writes softgels as "Softgel Capsule", so softgel has to be tested
144	 * before capsule or every softgel in the library reads as a capsule.
145	 */
146	export function classifyForm(productForm: string | null | undefined): FormClass {
147	  const f = (productForm ?? '').toLowerCase();
148	  if (!f) return 'other';
149	  if (f.includes('gummy') || f.includes('gummies') || f.includes('chew')) return 'gummy';
150	  if (f.includes('softgel') || f.includes('soft gel')) return 'softgel';
151	  if (f.includes('capsule')) return 'capsule';
152	  if (f.includes('tablet') || f.includes('caplet')) return 'tablet';
153	  if (f.includes('powder')) return 'powder';
154	  if (f.includes('liquid') || f.includes('drops') || f.includes('tincture') || f.includes('oil'))
155	    return 'liquid';
156	  return 'other';
157	}
158	
159	/** The onboarding option ids, in the same order as the question. */
160	const FORM_OPTION: Record<string, FormClass> = {
161	  capsule: 'capsule',
162	  tablet: 'tablet',
163	  softgel: 'softgel',
164	  powder: 'powder',
165	  liquid: 'liquid',
166	  gummy: 'gummy',
167	};
168	
169	const FORM_PLURAL: Record<FormClass, string> = {
170	  capsule: 'capsules',
171	  softgel: 'softgels',
172	  tablet: 'tablets',
173	  powder: 'powders',
174	  liquid: 'liquids',
175	  gummy: 'gummies',
176	  other: 'this form',
177	};
178	
179	/** A softgel is a capsule as far as swallowing one goes. */
180	const HARD_TO_SWALLOW: FormClass[] = ['capsule', 'softgel', 'tablet'];
181	const EASY_TO_SWALLOW: FormClass[] = ['powder', 'liquid'];
182	
183	/* ── the diet table (spec 2.1) ───────────────────────────────────────── */
184	
185	interface PriorityRule {
186	  /** the diet id that turns it on */
187	  when: string;
188	  group: readonly RegExp[];
189	  reason: string;
190	  /**
191	   * Pushes to the top of the list whatever the goals were, and keeps the
192	   * entry even when it matched no goal at all. Only B12 earns this.
193	   */
194	  required?: boolean;
195	  /** multiplier on the reference intake, where the published one differs */
196	  amountFactor?: number;
197	}
198	
199	const DIET_RULES: PriorityRule[] = [
200	  {
201	    when: 'no-meat',
202	    group: NUTRIENT.b12,
203	    required: true,
204	    reason: 'You said no meat — this is the one thing with no reliable plant source.',
205	  },
206	  {
207	    when: 'no-meat',
208	    group: NUTRIENT.iron,
209	    // NIH ODS: the recommended intake for vegetarians is 1.8× the RDA, because
210	    // non-haem iron absorbs far less well than the haem kind.
211	    amountFactor: 1.8,
212	    reason: 'Vegetarian iron targets are 1.8× the standard, because non-haem iron absorbs less well.',
213	  },
214	  {
215	    when: 'no-meat',
216	    group: NUTRIENT.zinc,
217	    reason: 'Phytate in grains and legumes binds zinc, so vegetarians can need up to 50% more.',
218	  },
219	  {
220	    when: 'no-dairy',
221	    group: NUTRIENT.calcium,
222	    reason: 'You said no dairy, which is where most people get most of their calcium.',
223	  },
224	  {
225	    when: 'no-dairy',
226	    group: NUTRIENT.vitaminD,
227	    reason: 'You said no dairy — fortified milk is one of the few food sources of vitamin D.',
228	  },
229	  {
230	    when: 'no-eggs',
231	    group: NUTRIENT.choline,
232	    reason: 'You said no eggs, which are the densest food source of choline.',
233	  },
234	];
235	
236	/* ── the swap table (spec 2.1 omega-3, 2.2 reactions) ────────────────── */
237	
238	interface SwapRule {
239	  /** the answer id that turns it on */
240	  when: string;
241	  /** which answer it comes from — a diet exclusion behaves differently below */
242	  from: 'diet' | 'reactions';
243	  /** every product of this nutrient */
244	  group: readonly RegExp[];
245	  /** the form to route to */
246	  prefer: RegExp[];
247	  /** the form to route away from; null means anything that is not preferred */
248	  avoid: RegExp[] | null;
249	  reason: string;
250	  /**
251	   * Whether the product routed *to* also moves onto a full stomach. Only
252	   * where the rule says so — a timing chip the card's own sentence does not
253	   * explain is the app inventing advice.
254	   */
255	  timingOnPrefer?: boolean;
256	  /**
257	   * What the card says when the catalogue holds nothing to route to. Null
258	   * means the nutrient is excluded outright rather than kept with a note —
259	   * only correct for a food the user does not eat, never for a reaction.
260	   */
261	  soloReason: string | null;
262	  /** the line under "what was left out" */
263	  swappedWhy: string;
264	}
265	
266	const SWAP_RULES: SwapRule[] = [
267	  {
268	    when: 'no-fish',
269	    from: 'diet',
270	    group: NUTRIENT.omega3,
271	    // "Vegan" on an omega-3 label means algal; there is no vegan fish oil
272	    prefer: [/algal/, /algae/, /vegan/, /schizochytrium/],
273	    avoid: null,
274	    reason: 'Algal rather than fish oil, because you don’t eat fish.',
275	    soloReason: null,
276	    swappedWhy: 'you don’t eat fish, and this one is fish-derived',
277	  },
278	  {
279	    when: 'iron-gi',
280	    from: 'reactions',
281	    group: NUTRIENT.iron,
282	    prefer: [/glycinate/],
283	    avoid: [/sulfate/, /sulphate/, /fumarate/],
284	    reason: 'Bisglycinate rather than sulfate, since iron has upset your stomach before.',
285	    soloReason: 'This is the only iron we have — take it with food.',
286	    swappedWhy: 'iron has upset your stomach, and the bisglycinate is gentler',
287	  },
288	  {
289	    when: 'mag-gi',
290	    from: 'reactions',
291	    group: NUTRIENT.magnesium,
292	    prefer: [/glycinate/],
293	    // citrate and oxide draw water into the bowel; glycinate does not. Other
294	    // salts — threonate, malate — are neither preferred nor avoided.
295	    avoid: [/citrate/, /oxide/],
296	    reason: 'Glycinate rather than citrate, since magnesium has loosened your stools before.',
297	    soloReason: 'This is the only magnesium we have — take it with food.',
298	    swappedWhy: 'citrate and oxide are the loosening ones, and the glycinate is not',
299	  },
300	  {
301	    when: 'fishoil-burp',
302	    from: 'reactions',
303	    group: NUTRIENT.omega3,
304	    prefer: [/algal/, /algae/, /vegan/, /schizochytrium/, /enteric/],
305	    avoid: null,
306	    reason: 'Algal rather than fish oil, since fish oil repeats on you.',
307	    timingOnPrefer: true,
308	    soloReason: 'This is the only omega-3 we have — take it with food.',
309	    swappedWhy: 'fish oil repeats on you, and the algal one does not',
310	  },
311	  {
312	    when: 'niacin-flush',
313	    from: 'reactions',
314	    group: NUTRIENT.niacin,
315	    prefer: [/niacinamide/, /nicotinamide/],
