import { readFileSync } from 'node:fs';

const M17 = readFileSync('supabase/migrations/0017_library_rebuild.sql', 'utf8');

/** Tokenise every single-quoted SQL string literal, honouring '' escapes. */
function strings(sql) {
  const out = [];
  let i = 0;
  while (i < sql.length) {
    if (sql[i] !== "'") { i++; continue; }
    i++;
    let buf = '';
    while (i < sql.length) {
      if (sql[i] === "'" && sql[i + 1] === "'") { buf += "'"; i += 2; continue; }
      if (sql[i] === "'") { i++; break; }
      buf += sql[i++];
    }
    out.push(buf);
  }
  return out;
}

const rows = [];

// (a) the 24 existing entries, re-branded by 0017's update statements
for (const line of M17.split('\n')) {
  if (!line.startsWith('update public.glossary set name =')) continue;
  const t = strings(line);
  // name, brand, product_form, label_url, slug
  rows.push({ old: t[4], brand: t[1], name: t[0], src: '0017 update' });
}

// (b) the 50 inserted entries
const body = M17.slice(M17.indexOf('-- ── 50 further'), M17.indexOf('on conflict (slug) do update'));
for (const chunk of body.split(/\n\n/)) {
  if (!/^\s*\('/.test(chunk)) continue;
  const t = strings(chunk);
  const k = t.indexOf('supplement');
  if (k < 0) throw new Error('no kind token: ' + chunk.slice(0, 60));
  rows.push({ old: t[0], brand: t[k + 1], name: t[1], src: '0017 insert' });
}

/* ── the derivation ───────────────────────────────────────────────────── */

const slugify = (s) =>
  s
    .toLowerCase()
    .replace(/[’']/g, '')            // Vinco's -> vincos
    .replace(/\.(com|co|net)\b/g, '') // BulkSupplements.com -> bulksupplements
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

const productSlug = (brand, name) => {
  const b = slugify(brand);
  let n = slugify(name);
  // the DSLD product name already carries the brand in every row; strip it so
  // the slug says the brand once
  if (n === b) return b;
  if (n.startsWith(b + '-')) n = n.slice(b.length + 1);
  return `${b}-${n}`;
};

let prefixed = 0;
for (const r of rows) {
  r.brandPrefix = slugify(r.name).startsWith(slugify(r.brand) + '-') || slugify(r.name) === slugify(r.brand);
  if (r.brandPrefix) prefixed++;
  r.next = productSlug(r.brand, r.name);
}

console.log(`rows: ${rows.length}  brand-prefixed names: ${prefixed}/${rows.length}`);

const seen = new Map();
for (const r of rows) {
  if (seen.has(r.next)) console.log(`!! COLLISION ${r.next}: ${seen.get(r.next)} / ${r.old}`);
  seen.set(r.next, r.old);
}
const olds = new Set(rows.map((r) => r.old));
for (const r of rows) if (olds.has(r.next) && r.next !== r.old) console.log(`!! new collides with an old slug: ${r.next}`);

const longest = rows.slice().sort((a, b) => b.next.length - a.next.length)[0];
console.log(`longest: ${longest.next.length} chars — ${longest.next}`);

console.log('\n--- mapping ---');
for (const r of rows) console.log(`${r.old.padEnd(22)} -> ${r.next}`);

console.log('\n--- names that do NOT start with their brand ---');
for (const r of rows) if (!r.brandPrefix) console.log(`  brand="${r.brand}" name="${r.name}"`);

console.log('\n--- SQL values ---');
for (const r of rows) console.log(`  ('${r.old}', '${r.next}'),`);

