cat >> tmp_slugs.mjs <<'EOF'

/* ── does any product fall out of a recommender rule group? ───────────── */
const GROUPS = {
  b12: [/\bb-?12\b/, /cobalamin/],
  iron: [/\biron\b/, /ferrous/, /ferric/],
  zinc: [/\bzinc\b/],
  magnesium: [/\bmagnesium\b/],
  omega3: [/\bomega[\s-]?3\b/, /\bdha\b/, /\bepa\b/, /fish oil/, /\bkrill\b/, /cod liver/],
  calcium: [/\bcalcium\b/],
  vitaminD: [/\bvitamin\s?d\b/, /\bd-?3\b/, /cholecalciferol/],
  choline: [/choline/],
  niacin: [/niacin/, /nicotinamide/, /nicotinic/],
  'prefer:algal': [/algal/, /algae/, /vegan/, /schizochytrium/, /enteric/],
  'prefer:glycinate': [/glycinate/],
  'avoid:ironsalt': [/sulfate/, /sulphate/, /fumarate/],
  'avoid:magsalt': [/citrate/, /oxide/],
  'prefer:niacinamide': [/niacinamide/, /nicotinamide/],
  'avoid:nicotinic': [/\bniacin\b/, /nicotinic/],
};
console.log('\n--- rule-group membership changes ---');
let lost = 0;
for (const r of rows) {
  const before = `${r.name} ${r.old}`.toLowerCase();
  const after = `${r.name} ${r.next}`.toLowerCase();
  for (const [g, terms] of Object.entries(GROUPS)) {
    const b = terms.some((t) => t.test(before));
    const a = terms.some((t) => t.test(after));
    if (b && !a) { lost++; console.log(`  LOST  ${g.padEnd(20)} ${r.old} — "${r.name}"`); }
    if (!b && a) console.log(`  GAINED ${g.padEnd(20)} ${r.old} — "${r.name}"`);
  }
}
console.log(lost === 0 ? '  none lost, none gained' : `  ${lost} lost`);
EOF
node tmp_slugs.mjs 2>&1 | sed -n '/rule-group membership changes/,$p'

