147	  for m in select old_slug, new_slug from _slug_rename_0020 order by old_slug loop
148	    -- Both present is the one state this cannot resolve on its own: it means
149	    -- two rows now claim the same product, and picking which to keep is a
150	    -- judgement about user data hanging off the ids, not a migration.
151	    if exists (select 1 from public.glossary where slug = m.old_slug)
152	       and exists (select 1 from public.glossary where slug = m.new_slug) then
153	      raise exception
154	        'slug rename: % and % both exist — resolve by hand before re-running',
155	        m.old_slug, m.new_slug;
156	    end if;
157	
158	    if exists (select 1 from public.glossary where slug = m.new_slug) then
159	      already := already + 1;                       -- already applied
160	    elsif exists (select 1 from public.glossary where slug = m.old_slug) then
161	      update public.glossary set slug = m.new_slug where slug = m.old_slug;
162	      renamed := renamed + 1;
163	    else
164	      -- Neither shape is present. Not fatal on its own — it means 0017 has not
165	      -- been applied to this database yet — but say so, loudly, because the
166	      -- alternative reading is that a product silently went missing.
167	      missing := missing + 1;
168	      raise notice 'slug rename: neither % nor % is present', m.old_slug, m.new_slug;
169	    end if;
170	  end loop;
171	
172	  raise notice
